// Données des promenades — RÉELLES, extraites de notre base le 28/10/2026.
//
// Source : OpenStreetMap, via public.sentiers_traces (moisson du 25/10/2026),
// sous licence ODbL — l'attribution est affichée sur la carte et sur la fiche.
//
// 🔴 POURQUOI SEULEMENT DEUX PROMENADES, ET POURQUOI PAS CROZON
// Sur les 6 554 tracés de la base, 299 seulement passent le contrôle
// géométrique (4,6 %) : ailleurs, les morceaux du sentier sont recollés sans
// être remis dans l'ordre, ce qui produit des cordes droites de 400 m et des
// coordonnées répétées. En Bretagne, DEUX tracés passent — ceux d'ici.
// En Finistère : AUCUN sur 132. Donc pas de promenade de la presqu'île de
// Crozon tant que la moisson n'est pas réparée (correctif en cours : ordonner
// et orienter les ways avant de les assembler).
//
// ⛔ NE PAS AJOUTER UN TRACÉ SANS LE PASSER À verifierTrace() — walks.test.ts
//    l'exécute sur chaque promenade livrée, et `npm run build` lance les tests.
//
// CE QU'ON N'AFFICHE PAS, FAUTE DE LE SAVOIR :
//   · l'altitude — aucun relief en base, donc aucun profil (il serait inventé) ;
//   · la difficulté, l'accès poussette/PMR, les chiens — absents d'OSM ;
//   · la durée est une ESTIMATION à 3,5 km/h, annoncée comme telle.

/** Au-delà, c'est certainement une corde : le moissonneur découpe déjà à 500 m. */
const SAUT_MAX_M = 600;
/** Part de points répétés tolérée — voir verifierTrace(). */
const PART_REPETES_MAX = 0.08;

export interface WalkPoint { lat: number; lon: number }

export interface Etape {
  nom: string;
  categorie: string;
  /** Position LE LONG du chemin, de 0 (départ) à 1 (arrivée). */
  pos: number;
  lat: number;
  lon: number;
}

export interface Walk {
  slug: string;
  titre: string;
  lieu: string;
  resume: string;
  distanceKm: number;
  /** Marche à 3,5 km/h — une estimation, jamais un relevé. */
  dureeEstimeeH: number;
  boucle: boolean;
  osmUrl: string;
  osmRef: string;
  points: WalkPoint[];
  etapes: Etape[];
}


